impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation, OV: gx::Orientation> gx::Transform<Flector<S, T, O>> for gx::Unit<Translator<(), T, OV>> {
    type Output = Flector<S, T, O>;
    #[inline(always)]
    fn transform(self, x: Flector<S, T, O>) -> Flector<S, T, O> {
        let v = self.into_inner().c;
        #[cfg(feature = "check-units")]
        {
        let u1 = v[0].mul_add(v[0], -T::from_i64(1));
            T::check_unit(&[u1]);
        }
        if let Some(xv) = gx::slots::values::<S, T, 4>(&x.c) {
        let t0 = v[0] * v[0];
        let t1 = xv[0] * t0;
        let t2 = xv[1] * t0;
        let t4 = v[0] * v[1];
        let t6 = v[0] * v[2];
        let t7 = xv[0] * t6;
        let t8 = xv[3] * t0;
        let t9 = (-xv[1]).mul_add(t4, t7);
        let t10 = t9 * T::from_i64(2);
        let t11 = xv[2].mul_add(t0, t10);
            return Flector { o: core::marker::PhantomData, c: gx::slots::from_values::<S, T, 4>([t1, t2, t11, t8]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[0] * v[2];
        let m2 = v[0] * v[1];
        let m3 = m1 * T::from_i64(2);
        let m4 = m2 * T::from_i64(2);
        let m5 = -m4;
        let x = x.c.map(gx::__private::SlotArr::<S, T>);
        Flector { o: core::marker::PhantomData, c: [(x[0].scale(m0)).0, (x[1].scale(m0)).0, (x[0].scale(m3) + x[1].scale(m5) + x[2].scale(m0)).0, (x[3].scale(m0)).0] }
    }
}

