impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation, OV: gx::Orientation> gx::Transform<Multivector<S, T, O>> for gx::Unit<Translator<(), T, OV>> {
    type Output = Multivector<S, T, O>;
    #[inline(always)]
    fn transform(self, x: Multivector<S, T, O>) -> Multivector<S, T, O> {
        let v = self.into_inner().c;
        #[cfg(feature = "check-units")]
        {
        let u1 = v[0].mul_add(v[0], -T::from_i64(1));
            T::check_unit(&[u1]);
        }
        if let Some(xv) = gx::slots::values::<S, T, 8>(&x.c) {
        let t0 = v[0] * v[0];
        let t1 = v[0] * v[1];
        let t2 = v[0] * v[2];
        let t3 = xv[0] * t0;
        let t6 = xv[2] * t2;
        let t7 = xv[2] * t0;
        let t8 = xv[3] * t0;
        let t10 = xv[6] * t1;
        let t11 = xv[5] * t0;
        let t12 = xv[6] * t2;
        let t13 = xv[6] * t0;
        let t14 = xv[7] * t0;
        let t15 = (-xv[3]).mul_add(t1, t6);
        let t16 = t15 * T::from_i64(2);
        let t17 = xv[1].mul_add(t0, t16);
        let t18 = t10 * T::from_i64(2);
        let t19 = xv[4].mul_add(t0, t18);
        let t21 = (-t12).mul_add(T::from_i64(2), t11);
            return Multivector { o: core::marker::PhantomData, c: gx::slots::from_values::<S, T, 8>([t3, t17, t7, t8, t19, t21, t13, t14]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[0] * v[1];
        let m2 = v[0] * v[2];
        let m3 = m2 * T::from_i64(2);
        let m4 = m1 * T::from_i64(2);
        let m5 = -m4;
        let m6 = -m3;
        let x = x.c.map(gx::__private::SlotArr::<S, T>);
        Multivector { o: core::marker::PhantomData, c: [(x[0].scale(m0)).0, (x[1].scale(m0) + x[2].scale(m3) + x[3].scale(m5)).0, (x[2].scale(m0)).0, (x[3].scale(m0)).0, (x[4].scale(m0) + x[6].scale(m4)).0, (x[5].scale(m0) + x[6].scale(m6)).0, (x[6].scale(m0)).0, (x[7].scale(m0)).0] }
    }
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation, OV: gx::Orientation> gx::TransformInv<Multivector<S, T, O>> for gx::Unit<Translator<(), T, OV>> {
    type Output = Multivector<S, T, O>;
    #[inline(always)]
    fn transform_inv(self, x: Multivector<S, T, O>) -> Multivector<S, T, O> {
        gx::Transform::transform(gx::Unit::new_unchecked(self.into_inner().reverse()), x)
    }
}

impl<T: gx::Coef, O: gx::Orientation, OV: gx::Orientation> gx::Prepare<Multivector<(), f64, O>> for gx::Unit<Translator<(), T, OV>> {
    type Output = gx::Prepared<gx::Unit<Translator>, Multivector<(), f64, O>, T, 5>;
    #[inline]
    fn prepare(self) -> gx::Prepared<gx::Unit<Translator>, Multivector<(), f64, O>, T, 5> {
        let v = self.into_inner().c;
        #[cfg(feature = "check-units")]
        {
        let u1 = v[0].mul_add(v[0], -T::from_i64(1));
            T::check_unit(&[u1]);
        }
        let m0 = v[0] * v[0];
        let m1 = v[0] * v[1];
        let m2 = v[0] * v[2];
        let m3 = m2 * T::from_i64(2);
        let m4 = m1 * T::from_i64(2);
        let m5 = -m4;
        let m6 = -m3;
        gx::Prepared::from_entries([m0, m3, m5, m4, m6])
    }
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> gx::Transform<Multivector<S, T, O>> for gx::Prepared<gx::Unit<Translator>, Multivector<(), f64, O>, T, 5> {
    type Output = Multivector<S, T, O>;
    #[inline(always)]
    fn transform(self, x: Multivector<S, T, O>) -> Multivector<S, T, O> {
        let m = self.m;
        let x = x.c.map(gx::__private::SlotArr::<S, T>);
        Multivector { o: core::marker::PhantomData, c: [(x[0].scale(m[0])).0, (x[1].scale(m[0]) + x[2].scale(m[1]) + x[3].scale(m[2])).0, (x[2].scale(m[0])).0, (x[3].scale(m[0])).0, (x[4].scale(m[0]) + x[6].scale(m[3])).0, (x[5].scale(m[0]) + x[6].scale(m[4])).0, (x[6].scale(m[0])).0, (x[7].scale(m[0])).0] }
    }
}

